SELECT reward_id AS rewardId,source_request_id AS sourceRequestId,stable_claims_digest AS stableClaimsDigest,qualification_revision AS qualificationRevision,
 confirmation_id AS confirmationId,authorization_sequence AS authorizationSequence,confirmed_seconds AS confirmedSeconds,confirmed_nanos AS confirmedNanos
FROM mk_referral_authorization_receipt WHERE tenant_id=#{tenant} AND reward_id=#{reward}
